// АВТОСГЕНЕРИРОВАНО из сохранённой таблицы library.dozory.ru (docs/MAGIC_TABLE.md).
// Названия/школы/уровни/ТИП(элемент) и боевой флаг — КАНОН из таблицы. Числа
// (baseCost/baseDamage/castTicks/effectPower) — НАШИ, по формуле от уровня; урон
// масштабируется от вложенной Силы (оверчардж). Уровень: 7 слабый … 1 сильный,
// 0 = «вне категорий». Иной уровня L владеет заклинанием, если spell.level >= L.

export type DamageType =
  | 'physical' | 'fire' | 'cold' | 'energy'
  | 'mental' | 'inferno' | 'information' | 'vital' | 'barrier' | 'poison';

export type SpellCategory =
  | 'damage' | 'heal' | 'shield' | 'drain' | 'dispel' | 'sunder'
  | 'control' | 'buff' | 'energy' | 'scout' | 'transform' | 'util' | 'misc';

export interface Spell {
  id: string; name: string; school: string;
  /** Мин. уровень Иного: 7 слабый … 1 сильный, 0 = вне категорий. */
  level: number;
  /** Общая школа (доступна магу) vs классовая. */
  general: boolean;
  category: SpellCategory;
  /** Применяется в бою (канон «Примен: Бой»). */
  combat: boolean;
  type: DamageType;
  baseCost: number; baseDamage: number; castTicks: number;
  effect?: 'interrupt' | 'shield' | 'sleep' | 'drain' | 'dominate' | 'heal' | 'dispel' | 'lifedrain';
  effectPower?: number; livingOnly?: boolean; desc: string;
}

